#!/usr/bin/env Rscript

# English forest plots for manuscript Fig. 5 and Fig. 6.
# Uses the audited meta-analysis summary CSV files generated by:
#   make_fig3_4_management_meta_forest.R
#   make_fig3_5_n_reduction_meta_forest.R

project_dir <- normalizePath(getwd())
local_lib <- file.path(project_dir, "Rlib")
if (dir.exists(local_lib)) .libPaths(c(local_lib, .libPaths()))

required_packages <- c("dplyr", "ggplot2", "patchwork", "grid", "showtext", "sysfonts")
missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]
if (length(missing_packages) > 0) {
  stop("Missing R package(s): ", paste(missing_packages, collapse = ", "), call. = FALSE)
}

suppressPackageStartupMessages({
  library(dplyr)
  library(ggplot2)
  library(patchwork)
  library(grid)
  library(showtext)
  library(sysfonts)
})

output_dir <- file.path(project_dir, "output", "figures")
fig5_summary_file <- file.path(output_dir, "Fig3-4_management_meta_summary.csv")
fig6_summary_file <- file.path(output_dir, "Fig3-5_N_reduction_meta_summary.csv")

if (!file.exists(fig5_summary_file) || !file.exists(fig6_summary_file)) {
  stop("Run the Fig. 5/Fig. 6 meta-analysis scripts before this English plotting script.",
       call. = FALSE)
}

font_candidates <- c(
  "/Library/Fonts/Arial Unicode.ttf",
  "/System/Library/Fonts/Supplemental/Arial Unicode.ttf",
  "/System/Library/Fonts/STHeiti Medium.ttc",
  "/System/Library/Fonts/Supplemental/Arial.ttf"
)
font_path <- font_candidates[file.exists(font_candidates)][1]
if (is.na(font_path)) {
  stop("No usable font found. Checked: ", paste(font_candidates, collapse = ", "),
       call. = FALSE)
}
font_fam <- "fig56_en"
sysfonts::font_add(family = font_fam, regular = font_path)
showtext::showtext_auto(enable = TRUE)
showtext::showtext_opts(dpi = 600)

device_type <- if (Sys.info()[["sysname"]] == "Darwin" &&
                   isTRUE(capabilities("aqua"))) "quartz" else getOption("bitmapType", "cairo")

set_file_dpi <- function(path, dpi = 600) {
  if (Sys.info()[["sysname"]] != "Darwin") return(invisible(FALSE))
  if (!nzchar(Sys.which("sips")) || !file.exists(path)) return(invisible(FALSE))
  status <- system2(
    "sips",
    c("-s", "dpiWidth", dpi, "-s", "dpiHeight", dpi, path),
    stdout = FALSE, stderr = FALSE
  )
  invisible(identical(status, 0L) || is.null(status))
}

read_summary <- function(path) {
  dat <- read.csv(path, stringsAsFactors = FALSE, na.strings = c("", "NA"))
  dat$plot_ready <- as.logical(dat$plot_ready)
  dat$significant <- as.logical(dat$significant)
  dat
}

fmt_value_label <- function(effect_type, effect, ci_low, ci_high,
                            plot_ready, reason_not_plotted, k, n_refs) {
  out <- ifelse(
    !plot_ready & reason_not_plotted == "fewer_than_3_references",
    paste0("refs<3 (k=", k, ", refs=", n_refs, ")"),
    ifelse(!plot_ready, paste0("n<3 (k=", k, ")"), NA_character_)
  )
  ready <- isTRUE(plot_ready) | (!is.na(plot_ready) & plot_ready)
  out[ready & effect_type == "lnRR"] <-
    sprintf("%.1f [%.1f, %.1f]", effect[ready & effect_type == "lnRR"],
            ci_low[ready & effect_type == "lnRR"],
            ci_high[ready & effect_type == "lnRR"])
  out[ready & effect_type != "lnRR"] <-
    sprintf("%.2f [%.2f, %.2f]", effect[ready & effect_type != "lnRR"],
            ci_low[ready & effect_type != "lnRR"],
            ci_high[ready & effect_type != "lnRR"])
  out
}

theme_forest <- function() {
  theme_classic(base_family = font_fam, base_size = 9.0) +
    theme(
      plot.background   = element_rect(fill = "white", color = NA),
      panel.background  = element_rect(fill = "white", color = NA),
      panel.border      = element_rect(color = "#333333", fill = NA, linewidth = 0.45),
      axis.line         = element_blank(),
      axis.ticks        = element_line(color = "#555555", linewidth = 0.25),
      axis.ticks.length = unit(0.10, "cm"),
      axis.text         = element_text(size = 7.8, color = "#222222"),
      axis.title        = element_text(size = 8.2, color = "#222222"),
      plot.tag          = element_text(face = "bold", size = 10.0),
      plot.margin       = margin(5, 30, 5, 6)
    )
}

axis_limits <- function(df) {
  vals <- c(df$ci_low[df$plot_ready], df$ci_high[df$plot_ready], 0)
  vals <- vals[is.finite(vals)]
  if (length(vals) == 0) return(c(-1, 1))
  lo <- min(vals)
  hi <- max(vals)
  span <- max(hi - lo, 0.1)
  c(floor((lo - span * 0.12) * 10) / 10,
    ceiling((hi + span * 0.12) * 10) / 10)
}

make_panel <- function(plot_data, levels, label_lookup, shape_levels,
                       metric_name, tag, panel_title, x_lab, show_y_labels = FALSE) {
  df <- plot_data %>%
    filter(metric == metric_name) %>%
    mutate(y = match(as.character(label_en), rev(levels)))

  lim <- axis_limits(df)
  span <- lim[2] - lim[1]
  label_x <- lim[2] + span * 0.08
  full_y <- data.frame(
    y = seq_along(levels),
    label = label_lookup[rev(levels)]
  )

  ggplot(df, aes(y = y)) +
    geom_vline(xintercept = 0, linetype = "dashed", linewidth = 0.32, color = "#777777") +
    geom_segment(
      data = df %>% filter(plot_ready),
      aes(x = ci_low, xend = ci_high, yend = y, color = sig_class),
      linewidth = 0.72, lineend = "round"
    ) +
    geom_point(
      data = df %>% filter(plot_ready),
      aes(x = effect, fill = sig_class, shape = row_type_en),
      size = 2.45, stroke = 0.45, color = "#222222"
    ) +
    geom_text(
      aes(x = label_x, label = value_label),
      hjust = 0, family = font_fam, size = 2.05, color = "#222222"
    ) +
    scale_shape_manual(values = shape_levels, guide = "none") +
    scale_color_manual(
      values = c("Decrease" = "#2166AC", "Increase" = "#D6604D", "NS" = "#666666"),
      guide = "none"
    ) +
    scale_fill_manual(
      values = c("Decrease" = "#2166AC", "Increase" = "#D6604D", "NS" = "white"),
      guide = "none"
    ) +
    scale_y_continuous(
      limits = c(0.45, length(levels) + 0.55),
      breaks = full_y$y,
      labels = if (show_y_labels) full_y$label else rep("", nrow(full_y)),
      expand = expansion(mult = c(0, 0))
    ) +
    scale_x_continuous(
      limits = c(lim[1], label_x + span * 0.75),
      breaks = pretty(lim, n = 5),
      expand = expansion(mult = c(0, 0))
    ) +
    labs(title = panel_title, x = x_lab, y = NULL, tag = tag) +
    coord_cartesian(clip = "off") +
    theme_forest() +
    theme(
      plot.title = element_text(size = 8.6, face = "bold", hjust = 0.5,
                                margin = margin(0, 0, 4, 0)),
      axis.text.y = element_text(size = 7.7, hjust = 1, lineheight = 0.95),
      plot.tag.position = c(0.018, 0.985)
    )
}

save_plot <- function(fig, png_file, tiff_file) {
  png(filename = png_file, width = 210, height = 165, units = "mm",
      res = 600, type = device_type, bg = "white")
  print(fig)
  dev.off()
  set_file_dpi(png_file, 600)

  tiff(filename = tiff_file, width = 210, height = 165, units = "mm",
       res = 600, type = device_type, bg = "white")
  print(fig)
  dev.off()
  set_file_dpi(tiff_file, 600)
}

fig5_summary <- read_summary(fig5_summary_file)
fig5_levels <- c("Organic inputs", "Manure", "Straw return", "Mulching",
                 "Plastic film", "Straw mulching", "Biochar", "EEFs")
fig5_labels <- c(
  "Organic inputs" = "Organic inputs",
  "Manure" = "  Manure",
  "Straw return" = "  Straw return",
  "Mulching" = "Mulching",
  "Plastic film" = "  Plastic film",
  "Straw mulching" = "  Straw mulching",
  "Biochar" = "Biochar",
  "EEFs" = "EEFs"
)
fig5_map <- c(
  "manure+straw_return" = "Organic inputs",
  "manure" = "Manure",
  "straw_return" = "Straw return",
  "film+straw_mulching" = "Mulching",
  "film" = "Plastic film",
  "straw_mulching" = "Straw mulching",
  "biochar" = "Biochar",
  "enhanced" = "EEFs"
)

fig5_plot_data <- fig5_summary %>%
  mutate(
    label_en = factor(unname(fig5_map[measure]), levels = fig5_levels),
    row_type_en = if_else(as.character(label_en) %in% c("Organic inputs", "Mulching"),
                          "Overall", "Subgroup"),
    sig_class = case_when(
      plot_ready & ci_high < 0 ~ "Decrease",
      plot_ready & ci_low > 0 ~ "Increase",
      plot_ready ~ "NS",
      TRUE ~ "Insufficient"
    ),
    value_label = fmt_value_label(effect_type, effect, ci_low, ci_high,
                                  plot_ready, reason_not_plotted, k, n_refs)
  )

fig5 <- (
  make_panel(fig5_plot_data, fig5_levels, fig5_labels,
             c("Overall" = 23, "Subgroup" = 21),
             "N2O", "(A)", "N₂O emissions", "Change (%)", TRUE) |
    make_panel(fig5_plot_data, fig5_levels, fig5_labels,
               c("Overall" = 23, "Subgroup" = 21),
               "Yield", "(B)", "Crop yield", "Change (%)", TRUE)
) / (
  make_panel(fig5_plot_data, fig5_levels, fig5_labels,
             c("Overall" = 23, "Subgroup" = 21),
             "YSE", "(C)", "Yield-scaled N₂O emissions", "Change (%)", TRUE) |
    make_panel(fig5_plot_data, fig5_levels, fig5_labels,
               c("Overall" = 23, "Subgroup" = 21),
               "EF", "(D)", "EF", "Hedges' d", TRUE)
) +
  plot_annotation(
    title = "Meta-analysis of farming-practice effects on N₂O emissions, crop yield, YSE and EF",
    theme = theme(
      plot.title = element_text(family = font_fam, size = 10.8, face = "bold",
                                hjust = 0.5, margin = margin(0, 0, 4, 0))
    )
  )

fig6_summary <- read_summary(fig6_summary_file)
fig6_levels <- c("Overall", "Spring maize", "Spring wheat",
                 "N reduction <25%", "N reduction 25%-50%", "N reduction >50%")
fig6_labels <- c(
  "Overall" = "Overall",
  "Spring maize" = "  Spring maize",
  "Spring wheat" = "  Spring wheat",
  "N reduction <25%" = "  N reduction <25%",
  "N reduction 25%-50%" = "  N reduction 25%-50%",
  "N reduction >50%" = "  N reduction >50%"
)
fig6_map <- c(
  "overall" = "Overall",
  "spring_maize" = "Spring maize",
  "spring_wheat" = "Spring wheat",
  "red_lt25" = "N reduction <25%",
  "red_25_50" = "N reduction 25%-50%",
  "red_gt50" = "N reduction >50%"
)

fig6_plot_data <- fig6_summary %>%
  mutate(
    label_en = factor(unname(fig6_map[group]), levels = fig6_levels),
    row_type_en = case_when(
      group == "overall" ~ "Overall",
      group %in% c("spring_maize", "spring_wheat") ~ "Crop",
      TRUE ~ "N-reduction rate"
    ),
    sig_class = case_when(
      plot_ready & ci_high < 0 ~ "Decrease",
      plot_ready & ci_low > 0 ~ "Increase",
      plot_ready ~ "NS",
      TRUE ~ "Insufficient"
    ),
    value_label = fmt_value_label(effect_type, effect, ci_low, ci_high,
                                  plot_ready, reason_not_plotted, k, n_refs)
  )

shape_fig6 <- c("Overall" = 23, "Crop" = 21, "N-reduction rate" = 22)
fig6 <- (
  make_panel(fig6_plot_data, fig6_levels, fig6_labels, shape_fig6,
             "N2O", "(A)", "N₂O emissions", "Change (%)", TRUE) |
    make_panel(fig6_plot_data, fig6_levels, fig6_labels, shape_fig6,
               "Yield", "(B)", "Crop yield", "Change (%)", TRUE)
) / (
  make_panel(fig6_plot_data, fig6_levels, fig6_labels, shape_fig6,
             "YSE", "(C)", "Yield-scaled N₂O emissions", "Change (%)", TRUE) |
    make_panel(fig6_plot_data, fig6_levels, fig6_labels, shape_fig6,
               "EF", "(D)", "EF", "Hedges' d", TRUE)
) +
  plot_annotation(
    title = "Meta-analysis of N-reduction effects on N₂O emissions, crop yield, YSE and EF",
    theme = theme(
      plot.title = element_text(family = font_fam, size = 10.8, face = "bold",
                                hjust = 0.5, margin = margin(0, 0, 4, 0))
    )
  )

fig5_png <- file.path(output_dir, "Fig5_management_meta_forest_EN.png")
fig5_tiff <- file.path(output_dir, "Fig5_management_meta_forest_EN.tiff")
fig6_png <- file.path(output_dir, "Fig6_N_reduction_meta_forest_EN.png")
fig6_tiff <- file.path(output_dir, "Fig6_N_reduction_meta_forest_EN.tiff")

save_plot(fig5, fig5_png, fig5_tiff)
save_plot(fig6, fig6_png, fig6_tiff)

message("Output PNG : ", fig5_png)
message("Output TIFF: ", fig5_tiff)
message("Output PNG : ", fig6_png)
message("Output TIFF: ", fig6_tiff)
